/// <summary>
/// Table class for AVARUMGoodsGroupTable.
/// Provides methods for goods group management, existence checks, and retrieval.
/// </summary>
public class AVARUMGoodsGroupTable extends common
{
}

Method.Source:
/// <summary>
/// Determines if concurrent deletes should throw exception.
/// </summary>
/// <returns>
/// true if exception should be thrown; otherwise, false.
/// </returns>
public boolean shouldThrowExceptionOnZeroDelete()
{
    boolean ret;

    ret = super();

    return ret;
}

/// <summary>
/// Gets the label text for a non-existent goods group.
/// </summary>
/// <returns>
/// The label text indicating the goods group does not exist.
/// </returns>
public static String255 txtNotExist()
{
    return "@AVARUM:GoodsGroupDoesNotExists";
}

/// <summary>
/// Checks if a goods group with the specified ID exists.
/// </summary>
/// <param name="_goodsGroup">The goods group ID to check.</param>
/// <returns>
/// true if the goods group exists; otherwise, false.
/// </returns>
public static boolean exist(AVARUMGoodsGroupId _goodsGroup)
{
    return _goodsGroup && (select firstonly recId from AVARUMGoodsGroupTable
                                where AVARUMGoodsGroupTable.Id == _goodsGroup).recId != 0;
}

/// <summary>
/// Checks if a goods group exists and throws an error if it does not.
/// </summary>
/// <param name="_goodsGroup">The goods group ID to check.</param>
/// <returns>
/// true if the goods group exists; otherwise, throws an error and returns false.
/// </returns>
public static boolean checkExist(AVARUMGoodsGroupId _goodsGroup)
{
    if (_goodsGroup  && !AVARUMGoodsGroupTable::exist(_goodsGroup))
    {
        return Global::checkFailed(strFmt(AVARUMGoodsGroupTable::txtNotExist(),_goodsGroup));
    }

    return true;
}

/// <summary>
/// Finds a goods group by its ID.
/// </summary>
/// <param name="_goodsGroup">The goods group ID to find.</param>
/// <param name="_forUpdate">Indicates if the record should be locked for update.</param>
/// <returns>
/// The found AVARUMGoodsGroupTable record, or null if not found.
/// </returns>
public static AVARUMGoodsGroupTable find(AVARUMGoodsGroupId _goodsGroup, boolean _forUpdate = false)
{
    AVARUMGoodsGroupTable goodsGroup;

    if (_goodsGroup)
    {
        goodsGroup.selectForUpdate(_forUpdate);

        select firstonly goodsGroup
            where goodsGroup.Id == _goodsGroup;
    }

    return goodsGroup;
}

/// <summary>
/// Finds a goods group by its RecId.
/// </summary>
/// <param name="_recId">The RecId of the goods group to find.</param>
/// <param name="_forUpdate">Indicates if the record should be locked for update.</param>
/// <returns>
/// The found AVARUMGoodsGroupTable record, or null if not found.
/// </returns>
public static AVARUMGoodsGroupTable findRecId(RecId _recId, boolean _forUpdate = false)
{
    AVARUMGoodsGroupTable goodsGroup;

    if (_recId)
    {
        goodsGroup.selectForUpdate(_forUpdate);

        select firstonly goodsGroup
            where goodsGroup.RecId == _recId;
    }

    return goodsGroup;
}

/// <summary>
/// Gets the description text for a goods group in the specified language.
/// </summary>
/// <param name="_goodsGroup">The goods group ID.</param>
/// <param name="_languageId">The language ID. Defaults to the company's language.</param>
/// <returns>
/// The description text in the specified language, or the default description if not found.
/// </returns>
public static FreeTxt txt(AVARUMGoodsGroupId _goodsGroup, LanguageId _languageId = CompanyInfo::find().languageId)
{
    AVARUMGoodsGroupTable goodsGroup;
    LanguageTxt languageTxt;

    goodsGroup = AVARUMGoodsGroupTable::find(_goodsGroup);
    languageTxt = LanguageTxt::find(goodsGroup.tableId, goodsGroup.recId, _languageId);

    return languageTxt.txt ? languageTxt.txt : goodsGroup.Description;
}
